      worktreeLabel: sourceTab.worktreeLabel,
    });
    sourceLayout = {
      root: createLeafNode(leafId),
      activeLeafId: leafId,
      expandedLeafId: null,
      sessionIdsByLeafId: { [leafId]: "" },
